// Tests for the client-side visibility mirror. The golden expectations in the
// parity suites were generated by running the engine's own `line` and
// `visible_hexes` (`api/app/engine/hex_coords.py` / `visibility.py`) over the
// same inputs — if these fail after an engine change, regenerate the goldens
// and keep the mirror in lockstep.

import { describe, expect, it } from "vitest";

import { axialLine, hexKey, type Axial } from "@/board/hex";

import { gameState, hex, settlement, unit, coord } from "./testFixtures";
import { hasLineOfSight, terrainIndex, visibleHexes } from "./visibility";

function keys(coords: readonly Axial[]): string[] {
  return coords.map((c) => hexKey(c.q, c.r)).sort();
}

describe("axialLine (engine parity)", () => {
  // Each expectation is the engine's `line()` output for the same endpoints,
  // including the vertex-grazing cases where the epsilon nudge breaks the tie.
  const golden: Array<[Axial, Axial, Array<[number, number]>]> = [
    [coord(0, 0), coord(2, 0), [[0, 0], [1, 0], [2, 0]]],
    [coord(0, 0), coord(-2, 1), [[0, 0], [-1, 0], [-2, 1]]],
    [coord(0, 0), coord(2, -1), [[0, 0], [1, -1], [2, -1]]],
    [coord(0, 0), coord(0, 2), [[0, 0], [0, 1], [0, 2]]],
    [coord(1, -1), coord(-1, 1), [[1, -1], [0, 0], [-1, 1]]],
    [coord(0, 0), coord(3, -2), [[0, 0], [1, -1], [2, -1], [3, -2]]],
    [coord(2, 1), coord(2, 1), [[2, 1]]],
  ];

  it.each(golden)("matches the engine line from %o to %o", (a, b, expected) => {
    expect(axialLine(a, b).map((c) => [c.q, c.r])).toEqual(expected);
  });
});

describe("hasLineOfSight", () => {
  // A 5-wide corridor along r=0 with woods in the middle.
  const terrain = terrainIndex(
    gameState({
      hexes: [
        hex(coord(0, 0)),
        hex(coord(1, 0), "woods"),
        hex(coord(2, 0)),
        hex(coord(3, 0)),
      ],
    }),
  );

  it("sees an adjacent woods hex but not through it", () => {
    expect(hasLineOfSight(terrain, coord(0, 0), coord(1, 0))).toBe(true);
    expect(hasLineOfSight(terrain, coord(0, 0), coord(2, 0))).toBe(false);
    expect(hasLineOfSight(terrain, coord(0, 0), coord(3, 0))).toBe(false);
  });

  it("sees out of its own woods hex", () => {
    expect(hasLineOfSight(terrain, coord(1, 0), coord(3, 0))).toBe(true);
  });

  it("a hex always sees itself", () => {
    expect(hasLineOfSight(terrain, coord(1, 0), coord(1, 0))).toBe(true);
  });
});

/** The 5×5 axial square used by the engine-parity golden below. */
function paritySquare() {
  const woods = new Set(["3,1", "3,2", "2,3"]);
  const hexes = [];
  for (let q = 0; q < 5; q++) {
    for (let r = 0; r < 5; r++) {
      const terrain = woods.has(`${q},${r}`) ? "woods" : q === 0 && r === 0 ? "town" : "plains";
      hexes.push(hex(coord(q, r), terrain));
    }
  }
  return hexes;
}

describe("visibleHexes", () => {
  it("matches the engine's visible_hexes on the golden fixture", () => {
    // visible_hexes(state, "blue") from the engine over the identical state:
    // infantry at (2,2) (vision 2, woods-blocked to the east) plus the
    // controlled town's fixed radius 1 around (0,0).
    const state = gameState({
      hexes: paritySquare(),
      units: [
        unit(1, "blue", coord(2, 2)),
        unit(2, "red", coord(4, 4), { type: "armor" }),
      ],
      settlements: [settlement(coord(0, 0), "blue")],
    });

    const golden = [
      [0, 0], [0, 1], [0, 2], [0, 3], [0, 4],
      [1, 0], [1, 1], [1, 2], [1, 3], [1, 4],
      [2, 0], [2, 1], [2, 2], [2, 3],
      [3, 1], [3, 2],
    ].map(([q, r]) => hexKey(q, r));

    expect(keys(visibleHexes(state, "blue"))).toEqual(golden.sort());
  });

  it("enemy units and enemy settlements contribute nothing", () => {
    const state = gameState({
      hexes: paritySquare(),
      units: [unit(2, "red", coord(4, 4))],
      settlements: [settlement(coord(0, 0), "red")],
    });
    expect(visibleHexes(state, "blue")).toEqual([]);
  });

  it("a controlled settlement grants radius 1 with no unit present", () => {
    const state = gameState({
      hexes: paritySquare(),
      settlements: [settlement(coord(0, 0), "blue")],
    });
    // On-map neighbours of (0,0) plus itself.
    expect(keys(visibleHexes(state, "blue"))).toEqual(
      keys([coord(0, 0), coord(0, 1), coord(1, 0)]),
    );
  });

  it("off-map hexes are never reported visible", () => {
    const state = gameState({
      hexes: [hex(coord(0, 0)), hex(coord(1, 0))],
      units: [unit(1, "blue", coord(0, 0))],
    });
    expect(keys(visibleHexes(state, "blue"))).toEqual(keys([coord(0, 0), coord(1, 0)]));
  });
});
